//! Create a vault (RF-1 to RF-6): KDBX 4 with our own Argon2id, calibrated; `.keyx` v2 generated by us.
//!
//! `DatabaseConfig` is `#[non_exhaustive]`: it starts from `default()` (Argon2d with 1 MiB, never kept, ADR-0001)
//! and EVERY public field is overwritten. The Argon2id parameters go through the public `VariantDictionary`
//! route, so the core does not depend on `rust-argon2` just to name its version type (lab P4 b).

use std::{
    fmt::Write as _,
    path::{Path, PathBuf},
    time::{Duration, Instant},
};

use keepass::{
    Database, DatabaseKey,
    config::{
        CompressionConfig, DatabaseConfig, DatabaseVersion, InnerCipherConfig, KdfConfig,
        OuterCipherConfig, VariantDictionary,
    },
};
use sha2::{Digest, Sha256};
use zeroize::Zeroizing;

use super::{
    header::{Argon2Variant, FormatVersion, KDF_ARGON2ID, KdfParams},
    key::{KeyFile, MasterPassword, VaultKey},
    open::{self, OpenedVault},
};
use crate::{
    error::{CoreError, CoreResult},
    storage,
    vault::check_group_name,
};

/// Argon2 memory of every new vault (RF-2: 64 MiB or more; KeePass' default).
pub const NEW_VAULT_MEMORY_BYTES: u64 = 64 << 20;
/// Argon2 lanes of every new vault (KeePass' default).
pub const NEW_VAULT_PARALLELISM: u32 = 2;
/// Fewest Argon2 iterations of a new vault (RF-2).
pub const MIN_NEW_VAULT_ITERATIONS: u64 = 2;
/// Most Argon2 iterations of a new vault (RF-2).
pub const MAX_NEW_VAULT_ITERATIONS: u64 = 50;
/// What calibration aims at: the key derivation of one unlock (RF-2).
pub const CALIBRATION_TARGET: Duration = Duration::from_secs(1);
/// Most unlocks timed by one calibration (it ends earlier when the estimate repeats).
const MAX_MEASUREMENTS: usize = 6;
/// Only for timing an unlock during calibration: the throwaway vault is dropped right away.
const CALIBRATION_PASSWORD: &str = "almarioks-calibration";

/// The KDF of a new vault: Argon2id, [`NEW_VAULT_MEMORY_BYTES`], [`NEW_VAULT_PARALLELISM`] lanes and 2 to 50
/// iterations.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct NewVaultKdf {
    iterations: u64,
}

impl NewVaultKdf {
    /// A KDF with a fixed number of iterations (for tests, and for what a calibration already chose).
    ///
    /// # Errors
    /// [`CoreError::ArgumentoInvalido`] outside 2 to 50 iterations (RF-2).
    pub fn with_iterations(iterations: u64) -> CoreResult<Self> {
        if (MIN_NEW_VAULT_ITERATIONS..=MAX_NEW_VAULT_ITERATIONS).contains(&iterations) {
            Ok(Self { iterations })
        } else {
            Err(CoreError::ArgumentoInvalido)
        }
    }

    /// Argon2 iterations.
    #[must_use]
    pub fn iterations(self) -> u64 {
        self.iterations
    }

    /// The parameters as the header of the new vault will say them.
    #[must_use]
    pub fn params(self) -> KdfParams {
        KdfParams::Argon2 {
            variant: Argon2Variant::Id,
            memory_bytes: NEW_VAULT_MEMORY_BYTES,
            iterations: self.iterations,
            parallelism: NEW_VAULT_PARALLELISM,
        }
    }

    /// Picks the iterations whose unlock time comes closest to [`CALIBRATION_TARGET`] (RF-2), with an injected
    /// measurement so tests neither depend on the hardware nor sleep.
    ///
    /// Argon2 time grows linearly with the iterations: one measurement at 2, a proportional guess, then secant
    /// steps on the last two points until the estimate repeats (3 measurements on a linear machine, at most 6).
    /// The answer is the measured point closest to the target; on a tie, the stronger one. It never asks the
    /// measurement for less than 2 or more than 50 iterations.
    ///
    /// # Errors
    /// Whatever `measure` returns.
    pub fn calibrate(mut measure: impl FnMut(Self) -> CoreResult<Duration>) -> CoreResult<Self> {
        let target = micros(CALIBRATION_TARGET);
        let mut points: Vec<(u64, i128)> = Vec::new();
        let mut probe = |iterations: u64, points: &mut Vec<(u64, i128)>| -> CoreResult<i128> {
            let time = micros(measure(Self {
                iterations: clamp(iterations),
            })?);
            points.push((clamp(iterations), time));
            Ok(time)
        };

        let (mut a, mut time_a) = (MIN_NEW_VAULT_ITERATIONS, 0);
        time_a = probe(a, &mut points).map(|t| t.max(time_a))?;
        if time_a < target {
            let guess = if time_a <= 0 {
                MAX_NEW_VAULT_ITERATIONS
            } else {
                clamp_i128(round_div(i128::from(a) * target, time_a))
            };
            if guess != a {
                let (mut b, mut time_b) = (guess, probe(guess, &mut points)?);
                while points.len() < MAX_MEASUREMENTS {
                    let rise = time_b - time_a;
                    let run = i128::from(b) - i128::from(a);
                    if rise <= 0 || run == 0 {
                        break;
                    }
                    let next = clamp_i128(i128::from(b) + round_div((target - time_b) * run, rise));
                    if points.iter().any(|&(i, _)| i == next) {
                        break;
                    }
                    (a, time_a) = (b, time_b);
                    (b, time_b) = (next, probe(next, &mut points)?);
                }
            }
        }
        let best = points
            .iter()
            .min_by_key(|&&(iterations, time)| ((time - target).abs(), u64::MAX - iterations))
            .map_or(MIN_NEW_VAULT_ITERATIONS, |&(iterations, _)| iterations);
        Ok(Self { iterations: best })
    }

    /// [`Self::calibrate`] with [`measure_unlock`] on this machine. Takes a few seconds: call it off the UI thread.
    ///
    /// # Errors
    /// [`CoreError::GuardadoFallido`] if a throwaway vault cannot be built.
    pub fn calibrate_on_this_machine() -> CoreResult<Self> {
        Self::calibrate(measure_unlock)
    }
}

/// Times one unlock (the key derivation dominates) of an empty vault with this KDF, built and dropped in memory.
///
/// # Errors
/// [`CoreError::GuardadoFallido`] if the throwaway vault cannot be built or reopened.
pub fn measure_unlock(kdf: NewVaultKdf) -> CoreResult<Duration> {
    let key = || DatabaseKey::new().with_password(CALIBRATION_PASSWORD);
    let mut bytes = Vec::new();
    Database::with_config(database_config(kdf)?)
        .save(&mut bytes, key())
        .map_err(|_| CoreError::GuardadoFallido)?;
    let start = Instant::now();
    let version = FormatVersion { major: 4, minor: 1 };
    open::parse_guarded(&bytes, key(), version).map_err(|_| CoreError::GuardadoFallido)?;
    Ok(start.elapsed())
}

/// Name of a vault made by [`create_vault_file`], which predates the name parameter (decision pending).
pub const DEFAULT_VAULT_NAME: &str = "Bóveda";
/// History limits written into every new vault: KeePass 2's defaults (10 versions, 6 MiB), so a vault made here
/// does not grow its history without bound (RF-26; decision pending).
pub const NEW_VAULT_HISTORY_MAX_ITEMS: isize = 10;
/// See [`NEW_VAULT_HISTORY_MAX_ITEMS`].
pub const NEW_VAULT_HISTORY_MAX_SIZE: isize = 6 * 1024 * 1024;

/// The bytes of a new, empty KDBX 4 vault with this key, name and KDF (RF-1, RF-2). Salt and seeds are fresh.
/// The name is the root group's name (and the metadata's database name, as KeePass writes it).
///
/// # Errors
/// - [`CoreError::NombreVacio`], [`CoreError::CampoMuyLargo`], [`CoreError::CaracterNoPermitido`]: the name, by
///   the group-name rules (RF-52).
/// - [`CoreError::GuardadoFallido`] if the library cannot write it.
pub fn create_vault(key: &VaultKey, name: &str, kdf: NewVaultKdf) -> CoreResult<Vec<u8>> {
    let name = check_group_name(name)?;
    let mut db = Database::with_config(database_config(kdf)?);
    db.root_mut().name.clone_from(&name);
    db.meta.database_name = Some(name);
    db.meta.history_max_items = Some(NEW_VAULT_HISTORY_MAX_ITEMS);
    db.meta.history_max_size = Some(NEW_VAULT_HISTORY_MAX_SIZE);
    let mut bytes = Vec::new();
    db.save(&mut bytes, key.to_database_key()?)
        .map_err(|_| CoreError::GuardadoFallido)?;
    Ok(bytes)
}

/// The key file of a vault being created.
#[derive(Debug)]
pub enum NewKeyFile {
    /// Password only.
    None,
    /// A key file the owner already has, in any format of RF-87.
    Existing(KeyFile),
    /// Generate a new `.keyx` version 2 at this path, which must not exist (RF-5, RF-6).
    Generate(PathBuf),
}

/// Creates a vault file at `path` and, if asked, its new key file (RF-1 to RF-6). The creation counts as done only
/// after both files are read back from disk and the vault reopens with that key (RF-5).
///
/// Nothing that already exists is touched: both paths are checked before writing, and each file is created with
/// `create_new`. If anything fails afterwards, the files this call created are removed.
///
/// # Errors
/// - [`CoreError::LlaveVacia`]: no password (or an empty one) and no key file (RF-3); nothing is written.
/// - [`CoreError::ArchivoExiste`]: `path` or the new key file's path already exists (RF-4, RF-6).
/// - [`CoreError::GuardadoFallido`]: the disk refused, or what was read back does not reopen.
pub fn create_vault_file(
    path: &Path,
    password: Option<MasterPassword>,
    key_file: NewKeyFile,
    kdf: NewVaultKdf,
) -> CoreResult<OpenedVault> {
    create_named_vault_file(path, DEFAULT_VAULT_NAME, password, key_file, kdf)
}

/// [`create_vault_file`] with the vault's name (the root group's name, plan `vault_create{name}`).
///
/// # Errors
/// Those of [`create_vault_file`], then the name's ([`CoreError::NombreVacio`], [`CoreError::CampoMuyLargo`],
/// [`CoreError::CaracterNoPermitido`]) after the files are checked and before anything is written.
pub fn create_named_vault_file(
    path: &Path,
    name: &str,
    password: Option<MasterPassword>,
    key_file: NewKeyFile,
    kdf: NewVaultKdf,
) -> CoreResult<OpenedVault> {
    let password = password.filter(|p| !p.is_empty());
    if password.is_none() && matches!(key_file, NewKeyFile::None) {
        return Err(CoreError::LlaveVacia);
    }
    storage::ensure_absent(path)?;
    if let NewKeyFile::Generate(key_path) = &key_file {
        storage::ensure_absent(key_path)?;
    }
    let name = check_group_name(name)?;

    // Declared before the open handles, so they are closed before the cleanup runs.
    let mut created = storage::CreatedFiles::default();
    let mut vault_file = created.create_new(path)?;
    let key_file = match key_file {
        NewKeyFile::None => None,
        NewKeyFile::Existing(file) => Some(file),
        NewKeyFile::Generate(key_path) => {
            let generated = new_key_file()?;
            let mut file = created.create_new(&key_path)?;
            storage::write_and_sync(&mut file, generated.content())?;
            drop(file);
            let on_disk = Zeroizing::new(storage::read(&key_path)?);
            if on_disk.as_slice() != generated.content() {
                return Err(CoreError::GuardadoFallido);
            }
            Some(KeyFile::from_bytes(on_disk.to_vec())?)
        }
    };
    let key = VaultKey::new(password, key_file)?;
    storage::write_and_sync(&mut vault_file, &create_vault(&key, &name, kdf)?)?;
    drop(vault_file);
    let opened = open::open(&storage::read(path)?, &key).map_err(|_| CoreError::GuardadoFallido)?;
    created.keep();
    Ok(opened)
}

/// A new `.keyx` version 2 (KeePass 2 format, as in `docs/lab/kdbx-roundtrip`): 32 bytes from the operating
/// system's generator in hexadecimal, and the first 4 bytes of their SHA-256 as `Hash` (RF-5).
pub(crate) fn new_key_file() -> CoreResult<KeyFile> {
    let mut raw = Zeroizing::new([0u8; 32]);
    getrandom::fill(raw.as_mut_slice()).map_err(|_| CoreError::GuardadoFallido)?;
    let digest = Sha256::digest(raw.as_slice());
    let hash = hex::encode_upper(digest.get(..4).ok_or(CoreError::GuardadoFallido)?);
    let key_hex = Zeroizing::new(hex::encode_upper(raw.as_slice()));
    // Room for the whole file up front: no reallocation leaves a copy of the key behind.
    let mut xml = Zeroizing::new(String::with_capacity(512));
    write!(
        xml,
        "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<KeyFile>\n\t<Meta>\n\t\t<Version>2.0</Version>\n\t</Meta>\n\t<Key>\n\t\t<Data Hash=\"{hash}\">{}</Data>\n\t</Key>\n</KeyFile>\n",
        key_hex.as_str()
    )
    .map_err(|_| CoreError::GuardadoFallido)?;
    // Our own output goes through the same check as any key file.
    KeyFile::from_bytes(xml.as_bytes().to_vec())
}

fn database_config(kdf: NewVaultKdf) -> CoreResult<DatabaseConfig> {
    let mut config = DatabaseConfig::default();
    config.version = DatabaseVersion::KDB4(1);
    config.outer_cipher_config = OuterCipherConfig::ChaCha20;
    config.compression_config = CompressionConfig::GZip;
    config.inner_cipher_config = InnerCipherConfig::ChaCha20;
    config.kdf_config = argon2id(kdf)?;
    config.public_custom_data = None;
    Ok(config)
}

fn argon2id(kdf: NewVaultKdf) -> CoreResult<KdfConfig> {
    let mut dict = VariantDictionary::new();
    dict.set("$UUID", KDF_ARGON2ID.to_vec());
    dict.set("M", NEW_VAULT_MEMORY_BYTES);
    dict.set("I", kdf.iterations);
    dict.set("P", NEW_VAULT_PARALLELISM);
    dict.set("V", 0x13u32);
    dict.set("S", vec![0u8; 32]); // ignored: `save()` draws a fresh salt
    let (config, _salt): (KdfConfig, Vec<u8>) =
        dict.try_into().map_err(|_| CoreError::GuardadoFallido)?;
    Ok(config)
}

fn micros(duration: Duration) -> i128 {
    i128::try_from(duration.as_micros()).unwrap_or(i128::MAX)
}

/// `n / d` rounded to the nearest integer, halves away from zero; `d` must be positive.
fn round_div(n: i128, d: i128) -> i128 {
    if n >= 0 {
        (2 * n + d) / (2 * d)
    } else {
        -((-2 * n + d) / (2 * d))
    }
}

fn clamp(iterations: u64) -> u64 {
    iterations.clamp(MIN_NEW_VAULT_ITERATIONS, MAX_NEW_VAULT_ITERATIONS)
}

fn clamp_i128(iterations: i128) -> u64 {
    let low = i128::from(MIN_NEW_VAULT_ITERATIONS);
    let high = i128::from(MAX_NEW_VAULT_ITERATIONS);
    u64::try_from(iterations.clamp(low, high)).unwrap_or(MIN_NEW_VAULT_ITERATIONS)
}
